 1	/**
 2	 * RunEvent — the single vocabulary Vigil uses for everything it observes.
 3	 * Every event is appended to runs/<id>/events.jsonl and reduced into UI state.
 4	 */
 5	
 6	export type GateKind = "task" | "validation" | "regression" | "phase";
 7	export type Verdict = "pending" | "running" | "pass" | "fail" | "skipped";
 8	
 9	export interface TokenUsage {
10	  input: number;
11	  output: number;
12	  cacheRead: number;
13	  cacheCreate: number;
14	}
15	
16	export type RunEvent =
17	  | { t: number; kind: "run.start"; runId: string; mode: "plan" | "prompt"; label: string; model: string; baseUrl?: string; cwd: string }
18	  | { t: number; kind: "run.end"; runId: string; ok: boolean; reason?: string }
19	  | { t: number; kind: "plan.start"; planId: string; file: string; title?: string; gateIds: string[] }
20	  | { t: number; kind: "plan.end"; planId: string; verdict: "pass" | "fail" | "halted"; reason?: string; durationMs: number }
21	  | { t: number; kind: "session.init"; planId: string; sessionId: string; model: string; tools: string[]; cwd: string }
22	  | { t: number; kind: "session.result"; planId: string; subtype: string; costUsd: number; durationMs: number; turns: number; usage: TokenUsage; modelUsage: Record<string, { costUSD: number; inputTokens: number; outputTokens: number }> }
23	  | { t: number; kind: "assistant.text"; planId: string; text: string; parentToolUseId: string | null; final: boolean }
24	  | { t: number; kind: "assistant.delta"; planId: string; text: string; parentToolUseId: string | null }
25	  | { t: number; kind: "tool.start"; planId: string; toolUseId: string; name: string; input: unknown; parentToolUseId: string | null }
26	  | { t: number; kind: "tool.output"; planId: string; toolUseId: string; chunk: string }
27	  | { t: number; kind: "tool.end"; planId: string; toolUseId: string; ok: boolean; durationMs: number; output: string }
28	  | { t: number; kind: "hook"; planId: string; event: string; tool?: string; decision: "allow" | "deny" | "warn" | "observe"; reason?: string; latencyMs: number }
29	  | { t: number; kind: "gate.update"; planId: string; gateId: string; verdict: Verdict; reason?: string; evidence?: { path: string; present: boolean; bytes: number }[] }
30	  | { t: number; kind: "approval.request"; planId: string; requestId: string; tool: string; input: unknown }
31	  | { t: number; kind: "approval.resolve"; planId: string; requestId: string; behavior: "allow" | "deny"; by: "user" | "auto" | "rail" }
32	  | { t: number; kind: "probe"; name: string; ok: boolean; detail: string; latencyMs: number }
33	  | { t: number; kind: "log"; level: "debug" | "info" | "warn" | "error"; source: string; message: string }
34	  | { t: number; kind: "control"; action: "pause" | "resume" | "inject" | "interrupt" | "mode"; detail?: string };
35	
36	export type RunEventKind = RunEvent["kind"];
37	
38	export function now(): number {
39	  return Date.now();
40	}
