/**
 * RunEvent — the single vocabulary Vigil uses for everything it observes.
 * Every event is appended to runs/<id>/events.jsonl and reduced into UI state.
 */

export type GateKind = "task" | "validation" | "regression" | "phase";
export type Verdict = "pending" | "running" | "pass" | "fail" | "skipped";

export interface TokenUsage {
  input: number;
  output: number;
  cacheRead: number;
  cacheCreate: number;
}

export type RunEvent =
  | { t: number; kind: "run.start"; runId: string; mode: "plan" | "prompt"; label: string; model: string; baseUrl?: string; cwd: string }
  | { t: number; kind: "run.end"; runId: string; ok: boolean; reason?: string }
  | { t: number; kind: "plan.start"; planId: string; file: string; title?: string; gateIds: string[] }
  | { t: number; kind: "plan.end"; planId: string; verdict: "pass" | "fail" | "halted"; reason?: string; durationMs: number }
  | { t: number; kind: "session.init"; planId: string; sessionId: string; model: string; tools: string[]; cwd: string }
  | { t: number; kind: "session.result"; planId: string; subtype: string; costUsd: number; durationMs: number; turns: number; usage: TokenUsage; modelUsage: Record<string, { costUSD: number; inputTokens: number; outputTokens: number }> }
  | { t: number; kind: "assistant.text"; planId: string; text: string; parentToolUseId: string | null; final: boolean }
  | { t: number; kind: "assistant.delta"; planId: string; text: string; parentToolUseId: string | null }
  | { t: number; kind: "tool.start"; planId: string; toolUseId: string; name: string; input: unknown; parentToolUseId: string | null }
  | { t: number; kind: "tool.output"; planId: string; toolUseId: string; chunk: string }
  | { t: number; kind: "tool.end"; planId: string; toolUseId: string; ok: boolean; durationMs: number; output: string }
  | { t: number; kind: "hook"; planId: string; event: string; tool?: string; decision: "allow" | "deny" | "warn" | "observe"; reason?: string; latencyMs: number }
  | { t: number; kind: "gate.update"; planId: string; gateId: string; verdict: Verdict; reason?: string; evidence?: { path: string; present: boolean; bytes: number }[] }
  | { t: number; kind: "approval.request"; planId: string; requestId: string; tool: string; input: unknown }
  | { t: number; kind: "approval.resolve"; planId: string; requestId: string; behavior: "allow" | "deny"; by: "user" | "auto" | "rail" }
