  "name": "vigil",
  "version": "0.1.0",
  "description": "Agent-SDK TUI runner for gated validation plans and arbitrary prompts — every tool call, gate, hook and dollar visible live.",
  "type": "module",
  "bin": { "vigil": "./bin/vigil.js" },
