import { describe, it, expect } from "vitest";
import { initialState, reduce, summarizeInput } from "../src/state/reducer.js";
import type { RunEvent } from "../src/engine/events.js";

const t = 1000;
describe("reducer", () => {
  it("builds plan/gate views and tool cards from events", () => {
    let s = initialState();
    const evs: RunEvent[] = [
      { t, kind: "run.start", runId: "r", mode: "plan", label: "x", model: "m", cwd: "/w" },
      { t, kind: "plan.start", planId: "01-01", file: "f", gateIds: ["VG-1", "VG-2"] },
      { t, kind: "tool.start", planId: "01-01", toolUseId: "a", name: "Bash", input: { command: "npm run build" }, parentToolUseId: null },
      { t, kind: "tool.output", planId: "01-01", toolUseId: "a", chunk: "line1\nline2\n" },
      { t: t + 50, kind: "tool.end", planId: "01-01", toolUseId: "a", ok: true, durationMs: 50, output: "" },
      { t, kind: "assistant.delta", planId: "01-01", text: "Hel", parentToolUseId: null },
      { t, kind: "assistant.delta", planId: "01-01", text: "lo", parentToolUseId: null },
      { t, kind: "assistant.text", planId: "01-01", text: "Hello", parentToolUseId: null, final: true },
      { t, kind: "gate.update", planId: "01-01", gateId: "VG-1", verdict: "pass", evidence: [{ path: "vg1.txt", present: true, bytes: 3 }] },
      { t, kind: "hook", planId: "01-01", event: "PreToolUse", tool: "Bash", decision: "deny", reason: "no-git-stash", latencyMs: 1 },
      { t, kind: "session.result", planId: "01-01", subtype: "success", costUsd: 0.42, durationMs: 100, turns: 3, usage: { input: 10, output: 5, cacheRead: 0, cacheCreate: 0 }, modelUsage: {} },
      { t, kind: "plan.end", planId: "01-01", verdict: "pass", durationMs: 100 },
    ];
    for (const e of evs) s = reduce(s, e);
    expect(s.plans[0].verdict).toBe("pass");
    expect(s.plans[0].gates.map((g) => g.verdict)).toEqual(["pass", "pending"]);
    expect(s.tools.a.tail).toContain("line2");
    expect(s.tools.a.ok).toBe(true);
    expect(s.latencies).toEqual([50]);
    expect(s.toolCounts).toEqual({ Bash: 1 });
    expect(s.stream.filter((b) => b.kind === "text")).toHaveLength(1);
    expect(s.stream.find((b) => b.kind === "text")?.text).toBe("Hello");
    expect(s.hookCounts.deny).toBe(1);
    expect(s.costUsd).toBe(0.42);
    expect(s.diag.some((d) => d.text.includes("VG-1 → PASS"))).toBe(true);
  });
  it("summarizes tool inputs", () => {
    expect(summarizeInput("Bash", { command: "ls  -la" })).toBe("ls -la");
    expect(summarizeInput("Read", { file_path: "/a", offset: 10 })).toBe("/a (from line 10)");
