/**
 * Safety rails evaluated in PreToolUse. Each rail is a regex against a
 * flattened view of the tool call ("<tool> <json input>") plus optional path checks.
 */
export interface Rail {
  id: string;
  match: string; // regex source, case-insensitive
  tools?: string[]; // limit to these tools (default: all)
  action: "deny" | "warn";
  reason: string;
}

export interface RailHit {
  rail: Rail;
  action: "deny" | "warn";
  reason: string;
}

export const DEFAULT_RAILS: Rail[] = [
  { id: "no-git-stash", match: "\\bgit\\s+stash\\b", tools: ["Bash"], action: "deny", reason: "git stash is forbidden in this repo (shared object store; clobbers other sessions)" },
  { id: "no-checkout-main", match: "\\bgit\\s+(-C\\s+\\S*Desktop/OmniRoute(?!/\\.claude/worktrees)\\S*\\s+)?(checkout|switch)\\b(?![^\\n]*worktrees)", tools: ["Bash"], action: "deny", reason: "never git checkout/switch in the shared main checkout — use the worktree" },
  { id: "no-pkill-pattern", match: "\\b(pkill\\s+-f|killall)\\b", tools: ["Bash"], action: "deny", reason: "pattern kills have taken down unrelated services — kill by PID only" },
  { id: "no-agent-instruction-edits", match: "(CLAUDE|AGENTS|GEMINI)\\.md", tools: ["Write", "Edit", "MultiEdit"], action: "deny", reason: "agent-instruction files need explicit operator approval" },
  { id: "no-rm-rf-home", match: "\\brm\\s+-rf?\\s+(~|\\$HOME|/Users/\\w+)(/?\\s|$)", tools: ["Bash"], action: "deny", reason: "refusing to delete a home directory" },
  { id: "warn-real-omp-config", match: "\\.omp/agent/(models|config)\\.ya?ml", action: "warn", reason: "touches Nick's real omp config — expected only for read/sha checks" },
  { id: "warn-live-db", match: "\\.omniroute/storage\\.sqlite(?!.*\\.backup)", tools: ["Bash"], action: "warn", reason: "touches the live OmniRoute database" },
];

export function flattenToolCall(tool: string, input: unknown): string {
  if (input && typeof input === "object") {
    const o = input as Record<string, unknown>;
    const primary = (o.command ?? o.file_path ?? o.path ?? o.pattern ?? "") as string;
    return `${tool} ${primary} ${JSON.stringify(o)}`;
  }
  return `${tool} ${String(input ?? "")}`;
}

export function evaluateRails(rails: Rail[], tool: string, input: unknown): RailHit[] {
  const text = flattenToolCall(tool, input);
  const hits: RailHit[] = [];
  for (const rail of rails) {
    if (rail.tools && !rail.tools.includes(tool)) continue;
    let re: RegExp;
    try { re = new RegExp(rail.match, "i"); } catch { continue; }
    if (re.test(text)) hits.push({ rail, action: rail.action, reason: rail.reason });
  }
  // deny wins over warn
  return hits.sort((a, b) => (a.action === b.action ? 0 : a.action === "deny" ? -1 : 1));
}
