/** Blocks until the operator asks to re-run or quit after a failure. */
waitForDecision(): Promise<"rerun" | "quit"> {
  if (this.budgetExceeded) return Promise.resolve("quit");
  return new Promise((resolve) => { this.once("decision", resolve); });
