case "session.result": {
  // Run-level totals: a plan's result reports its own session total,
  // so on repeat results for the same plan only the delta counts.
  const prevCost = this.planCost.get(ev.planId) ?? 0;
  const prevTurns = this.planTurns.get(ev.planId) ?? 0;
  this.totalCostUsd += ev.costUsd - prevCost;
  this.totalTurns += ev.turns - prevTurns;
  this.planCost.set(ev.planId, ev.costUsd);
  this.planTurns.set(ev.planId, ev.turns);
  this.cost[ev.planId] = { costUsd: ev.costUsd, durationMs: ev.durationMs, turns: ev.turns, usage: ev.usage, modelUsage: ev.modelUsage };
  this.cost["totalCostUsd"] = this.totalCostUsd;
  this.cost["totalTurns"] = this.totalTurns;
  this.cost["updatedAt"] = ev.t;
  writeFileSync(join(this.dir, "cost.json"), JSON.stringify(this.cost, null, 2)); break;
}

private cost: Record<string, unknown> = {};
private planCost = new Map<string, number>();
private planTurns = new Map<string, number>();
private totalCostUsd = 0;
private totalTurns = 0;

