import { Command } from "commander";
import React from "react";
import { render } from "ink";
import { readFileSync, existsSync, statSync, readdirSync } from "node:fs";
import { resolve, join } from "node:path";
import { createRequire } from "node:module";
import { loadConfig } from "./config.js";
import { Runner } from "./engine/runner.js";
import { RunStore } from "./engine/store.js";
import { App } from "./ui/App.js";
import { initialState, reduce, type UIState } from "./state/reducer.js";
import { clockHHMMSS } from "./ui/anim.js";
import type { RunEvent } from "./engine/events.js";
import { renderReplay } from "./replay.js";

const require = createRequire(import.meta.url);
const pkg = require("../package.json") as { version: string };

const program = new Command();
program.name("vigil").description("Agent-SDK TUI runner for gated validation plans and arbitrary prompts").version(pkg.version);

function common(cmd: Command) {
  return cmd
    .option("-c, --config <file>", "vigil.config.json path")
    .option("--cwd <dir>", "working directory for the agent")
    .option("--model <id>", "model id (e.g. cc/claude-fable-5-1)")
    .option("--base-url <url>", "ANTHROPIC_BASE_URL for the agent")
    .option("--approvals <mode>", "auto | gates | all")
    .option("--plain", "no animation, line-oriented output (CI/logs)")
    .option("--log <level>", "diagnostics level: debug | info | warn")
    .option("--resume <sessionId>", "resume an SDK session id")
    .option("--claude-bin <path>", "path to the Claude Code executable (pathToClaudeCodeExecutable)")
    .option("--settings <sources>", "Claude Code settings to load: comma list of user,project,local (default: none — clean agent)");
}

async function launch(opts: Record<string, string | boolean | undefined>, mode: "plan" | "prompt", target?: string, prompt?: string, sel: { from?: string; to?: string; only?: string } = {}) {
  const { config, source } = loadConfig(opts.config as string | undefined);
  if (opts.model) config.model = String(opts.model);
  if (opts.baseUrl) config.baseUrl = String(opts.baseUrl);
  if (opts.log) config.logLevel = opts.log as "debug" | "info" | "warn";
  if (opts.settings) config.settingSources = String(opts.settings).split(",").map((s) => s.trim()).filter(Boolean) as Array<"user" | "project" | "local">;
  const approvals = ((opts.approvals as string) ?? config.approvals) as "auto" | "gates" | "all";
  const cwd = resolve((opts.cwd as string) ?? config.cwd ?? process.cwd());
  const animate = !opts.plain && config.animations && process.stdout.isTTY === true;
  const runner = new Runner({ config, mode, target, prompt, cwd, approvals, from: sel.from, to: sel.to, only: sel.only, resume: opts.resume as string | undefined, pathToClaudeCodeExecutable: opts.claudeBin as string | undefined });

  if (!animate && (opts.plain || !process.stdout.isTTY)) {
    // plain mode: stream a readable log, still full observability on disk
    let state: UIState = initialState();
    runner.on("event", (ev: RunEvent) => {
      state = reduce(state, ev);
      const line = plainLine(ev);
      if (line) process.stdout.write(line + "\n");
    });
    runner.on("approval", (req: { tool: string; resolve: (a: boolean) => void }) => { process.stdout.write(`[approval] ${req.tool} — auto-denied in --plain mode (use --approvals auto)\n`); req.resolve(false); });
    runner.on("gateApproval", (g: { gateId: string; resolve: (a: boolean) => void }) => { process.stdout.write(`[gate] ${g.gateId} accepted (plain mode)\n`); g.resolve(true); });
    // in plain mode a failure ends the run
    runner.on("event", (ev: RunEvent) => { if (ev.kind === "plan.end" && ev.verdict !== "pass") setTimeout(() => runner.decide("quit"), 10); });
    process.stdout.write(`vigil ${pkg.version} · config ${source} · ${mode} · approvals ${approvals} · cwd ${cwd}\n`);
    const ok = await runner.start();
    process.stdout.write(`\nRUN ${ok ? "PASS" : "FAIL"} · runs/${runner.store.runId}\n`);
    process.exit(ok ? 0 : 1);
  }

  const planModels = new Map<string, { gates: { id: string; criteria: string; capture: string[] }[]; file: string }>();
  const startPromise = runner.start();
  // models are parsed inside start(); expose them once discovered (synchronous part of start runs before first await)
  for (const [id, m] of runner.models) planModels.set(id, { gates: m.gates.map((g) => ({ id: g.id, criteria: g.criteria, capture: g.capture })), file: m.file });
  // Route stray stderr (SDK warnings, child noise) into diagnostics instead of smearing the cockpit.
  const origErr = process.stderr.write.bind(process.stderr);
  process.stderr.write = ((chunk: string | Uint8Array) => { const text = String(chunk).trim(); if (text) runner.emit("event", { t: Date.now(), kind: "log", level: /warn/i.test(text) ? "warn" : "error", source: "stderr", message: text.split("\n")[0].slice(0, 300) }); return true; }) as typeof process.stderr.write;
  const ink = render(React.createElement(App, { runner, animate, initialLevel: config.logLevel, planModels }), { exitOnCtrlC: true });
  process.on("exit", () => { process.stderr.write = origErr; });
  const ok = await startPromise;
  await ink.waitUntilExit();
  process.exit(ok ? 0 : 1);
}

function plainLine(ev: RunEvent): string | null {
  const ts = clockHHMMSS(ev.t);
  switch (ev.kind) {
    case "run.start": return `${ts} run ${ev.runId} (${ev.mode}) model=${ev.model}${ev.baseUrl ? ` via ${ev.baseUrl}` : ""}`;
    case "plan.start": return `${ts} ▶ plan ${ev.planId} gates=[${ev.gateIds.join(",")}]`;
    case "plan.end": return `${ts} ${ev.verdict === "pass" ? "✓" : "✗"} plan ${ev.planId} ${ev.verdict}${ev.reason ? " — " + ev.reason : ""} (${Math.round(ev.durationMs / 1000)}s)`;
    case "session.init": return `${ts} session ${ev.sessionId} model=${ev.model}`;
    case "session.result": return `${ts} result/${ev.subtype} turns=${ev.turns} cost=$${ev.costUsd.toFixed(3)}`;
    case "assistant.text": return ev.text.split("\n").filter((l) => l.trim()).map((l) => `${ts} ▍ ${l}`).join("\n");
    case "tool.start": return `${ts} ⚙ ${ev.name} ${JSON.stringify(ev.input).slice(0, 160)}`;
    case "tool.end": return `${ts}   └ ${ev.ok ? "ok" : "ERROR"} ${Math.round(ev.durationMs / 1000)}s ${ev.output.split("\n").slice(-1)[0]?.slice(0, 120) ?? ""}`;
    case "hook": return ev.decision === "observe" || ev.decision === "allow" ? null : `${ts} hook ${ev.event} ${ev.tool} ${ev.decision} — ${ev.reason}`;
    case "gate.update": return `${ts} gate ${ev.gateId} → ${ev.verdict.toUpperCase()}${ev.reason ? " — " + ev.reason : ""}${ev.evidence?.length ? ` evidence ${ev.evidence.filter((e) => e.present).length}/${ev.evidence.length}` : ""}`;
    case "probe": return ev.ok ? null : `${ts} probe ${ev.name} ✗ ${ev.detail}`;
    case "log": return ev.level === "debug" ? null : `${ts} ${ev.level} ${ev.source}: ${ev.message}`;
    case "control": return `${ts} ctl ${ev.action}${ev.detail ? ": " + ev.detail.slice(0, 100) : ""}`;
    case "run.end": return `${ts} run ${ev.ok ? "PASS" : "FAIL"}${ev.reason ? " — " + ev.reason : ""}`;
    default: return null;
  }
}

common(program.command("run").description("run gated PLAN.md files (a directory with phases/, or one PLAN.md)").argument("<target>").option("--from <planId>").option("--to <planId>").option("--only <planId>"))
  .action((target: string, opts) => launch(opts, "plan", target, undefined, { from: opts.from, to: opts.to, only: opts.only }));

common(program.command("prompt").description("run an arbitrary prompt with full observability").argument("[text]").option("-f, --file <path>", "read the prompt from a file"))
  .action((text: string | undefined, opts) => {
    const prompt = opts.file ? readFileSync(resolve(opts.file), "utf8") : text;
    if (!prompt) { console.error("prompt text or --file required"); process.exit(2); }
    return launch(opts, "prompt", undefined, prompt);
  });

program.command("replay").description("re-animate a recorded run from its events.jsonl").argument("<runDir>").option("--speed <x>", "playback speed multiplier", "20").option("--plain", "print instead of animating")
  .action(async (runDir: string, opts) => {
    const dir = resolve(runDir);
    const evs = RunStore.readEvents(dir);
    if (!evs.length) { console.error(`no events.jsonl in ${dir}`); process.exit(2); }
    if (opts.plain || !process.stdout.isTTY) { for (const ev of evs) { const l = plainLine(ev); if (l) console.log(l); } return; }
    await renderReplay(evs, Number(opts.speed));
  });

program.command("tail").description("follow a run's events.jsonl as readable lines").argument("<runDir>")
  .action(async (runDir: string) => {
    const f = join(resolve(runDir), "events.jsonl");
    let pos = 0;
    const pump = () => {
      if (!existsSync(f)) return;
      const size = statSync(f).size; if (size <= pos) return;
      const chunk = readFileSync(f, "utf8").slice(pos); pos = size;
      for (const line of chunk.split("\n").filter(Boolean)) { try { const l = plainLine(JSON.parse(line) as RunEvent); if (l) console.log(l); } catch { /* partial line */ } }
    };
    pump(); setInterval(pump, 500);
  });

program.command("runs").description("list recorded runs under a plan root").argument("<planRoot>")
  .action((root: string) => {
    const dir = join(resolve(root), "runs");
    if (!existsSync(dir)) { console.log("(no runs)"); return; }
    for (const r of readdirSync(dir).sort()) {
      const evs = RunStore.readEvents(join(dir, r));
      const end = evs.find((e) => e.kind === "run.end") as Extract<RunEvent, { kind: "run.end" }> | undefined;
      const cost = [...evs].reverse().find((e) => e.kind === "session.result") as Extract<RunEvent, { kind: "session.result" }> | undefined;
      console.log(`${r}  ${end ? (end.ok ? "PASS" : "FAIL") : "(in progress / crashed)"}  $${(cost?.costUsd ?? 0).toFixed(2)}  ${evs.length} events`);
    }
  });

program.parseAsync(process.argv).catch((e) => { console.error(e); process.exit(1); });

/**
 * RunEvent — the single vocabulary Vigil uses for everything it observes.
 * Every event is appended to runs/<id>/events.jsonl and reduced into UI state.
 */

export type GateKind = "task" | "validation" | "regression" | "phase";
export type Verdict = "pending" | "running" | "pass" | "fail" | "skipped";

export interface TokenUsage {
  input: number;
  output: number;
  cacheRead: number;
  cacheCreate: number;
}

export type RunEvent =
  | { t: number; kind: "run.start"; runId: string; mode: "plan" | "prompt"; label: string; model: string; baseUrl?: string; cwd: string }
  | { t: number; kind: "budget.warn"; runId: string; metric: "cost" | "turns"; thresholdPct: number; spent: number; cap: number; message: string }
  | { t: number; kind: "budget.exceeded"; runId: string; metric: "cost" | "turns"; spent: number; cap: number; message: string }
  | { t: number; kind: "run.end"; runId: string; ok: boolean; reason?: string }
  | { t: number; kind: "plan.start"; planId: string; file: string; title?: string; gateIds: string[] }
  | { t: number; kind: "plan.end"; planId: string; verdict: "pass" | "fail" | "halted"; reason?: string; durationMs: number }
  | { t: number; kind: "session.init"; planId: string; sessionId: string; model: string; tools: string[]; cwd: string }
  | { t: number; kind: "session.result"; planId: string; subtype: string; costUsd: number; durationMs: number; turns: number; usage: TokenUsage; modelUsage: Record<string, { costUSD: number; inputTokens: number; outputTokens: number }> }
  | { t: number; kind: "assistant.text"; planId: string; text: string; parentToolUseId: string | null; final: boolean }
  | { t: number; kind: "assistant.delta"; planId: string; text: string; parentToolUseId: string | null }
  | { t: number; kind: "tool.start"; planId: string; toolUseId: string; name: string; input: unknown; parentToolUseId: string | null }
  | { t: number; kind: "tool.output"; planId: string; toolUseId: string; chunk: string }
  | { t: number; kind: "tool.end"; planId: string; toolUseId: string; ok: boolean; durationMs: number; output: string }
  | { t: number; kind: "hook"; planId: string; event: string; tool?: string; decision: "allow" | "deny" | "warn" | "observe"; reason?: string; latencyMs: number }
  | { t: number; kind: "gate.update"; planId: string; gateId: string; verdict: Verdict; reason?: string; evidence?: { path: string; present: boolean; bytes: number }[] }
  | { t: number; kind: "approval.request"; planId: string; requestId: string; tool: string; input: unknown }
  | { t: number; kind: "approval.resolve"; planId: string; requestId: string; behavior: "allow" | "deny"; by: "user" | "auto" | "rail" }
  | { t: number; kind: "probe"; name: string; ok: boolean; detail: string; latencyMs: number }
  | { t: number; kind: "log"; level: "debug" | "info" | "warn" | "error"; source: string; message: string }
  | { t: number; kind: "control"; action: "pause" | "resume" | "inject" | "interrupt" | "mode"; detail?: string };

export type RunEventKind = RunEvent["kind"];

export function now(): number {
  return Date.now();
}
