/** Default executable: explicit option → CLAUDE_CODE_EXECPATH → `claude` on PATH → undefined (SDK default). */
export function resolveClaudeBin(explicit?: string): string | undefined {
  if (explicit) return explicit;
  if (process.env.CLAUDE_CODE_EXECPATH && existsSync(process.env.CLAUDE_CODE_EXECPATH)) return process.env.CLAUDE_CODE_EXECPATH;
  try { const p = execFileSync(process.platform === "win32" ? "where" : "which", ["claude"], { encoding: "utf8" }).split(/\r?\n/)[0].trim(); if (p && existsSync(p)) return p; } catch { /* not on PATH */ }
  return undefined;
}

export interface RunnerOpts {
  config: VigilConfig;
  mode: "plan" | "prompt";
  target?: string; // plan dir or PLAN.md
  prompt?: string;
  from?: string; to?: string; only?: string;
  cwd: string;
  approvals: ApprovalMode;
  label?: string;
  resume?: string;
  runsRoot?: string;
  pathToClaudeCodeExecutable?: string;
}

export class Runner extends EventEmitter {
  store!: RunStore;
  session: PlanSession | null = null;
  approvals: ApprovalMode;
  private stopProbes: (() => void) | null = null;
  private abort = false;
  private guard: BudgetGuard | null = null;
  /** True when a cost/turn cap was reached; cli exits with code 3. */
  budgetExceeded = false;
  private budgetExceededMetric: "cost" | "turns" | null = null;
  planRoot = "";
  plans: PlanRef[] = [];
  models = new Map<string, PlanModel>();
  private rerunRequested = false;

  constructor(readonly opts: RunnerOpts) { super(); this.approvals = opts.approvals; }

  private emitEv(ev: RunEvent) { this.store.append(ev); this.emit("event", ev); }

  requestStop() { this.abort = true; this.session?.close(); }
  requestRerun() { this.rerunRequested = true; }

  async start(): Promise<boolean> {
    const cfg = this.opts.config;
    let label = this.opts.label ?? "prompt";
    if (this.opts.mode === "plan") {
      const d = discoverPlans(this.opts.target!);
      this.planRoot = d.root;
      this.plans = selectPlans(d.plans, { from: this.opts.from, to: this.opts.to, only: this.opts.only });
      label = this.opts.label ?? this.planRoot.split("/").filter(Boolean).pop() ?? "plan";
      for (const p of this.plans) this.models.set(p.id, parsePlan(readFileSync(p.file, "utf8"), p.file));
    }
    const runsRoot = this.opts.runsRoot ?? (this.opts.mode === "plan" ? join(this.planRoot, "runs") : resolve(this.opts.cwd, ".vigil/runs"));
    this.store = new RunStore(runsRoot, RunStore.newRunId(label));
    this.emitEv({ t: now(), kind: "run.start", runId: this.store.runId, mode: this.opts.mode, label, model: cfg.model, baseUrl: cfg.baseUrl, cwd: this.opts.cwd });
    this.emitEv({ t: now(), kind: "log", level: "info", source: "vigil", message: `run dir ${this.store.dir}` });
    if (cfg.probes.length) this.stopProbes = startProbes(cfg.probes as ProbeDef[], (ev) => this.emitEv(ev));
    this.guard = new BudgetGuard({ maxBudgetUsd: cfg.maxBudgetUsd, maxTurns: cfg.maxTurns, warnThresholds: cfg.budgetWarnThresholds });

    let ok = true;
    if (this.opts.mode === "prompt") {
      const r = await this.runOne({ id: "prompt", prompt: this.opts.prompt!, plan: undefined });
      ok = r.verdict === "pass";
    } else {
      for (let i = 0; i < this.plans.length && !this.abort; i++) {
        const ref = this.plans[i];
        const model = this.models.get(ref.id)!;
        const evidenceDir = join(dirname(ref.file), "evidence");
        mkdirSync(evidenceDir, { recursive: true });
        const prompt = readFileSync(ref.file, "utf8") + "\n" + runnerContract(model, { evidenceDir, planRoot: this.planRoot });
        const r = await this.runOne({ id: ref.id, prompt, plan: model, evidenceDir });
        if (r.verdict !== "pass") {
          ok = false;
          this.writeReports(model, false);
          if (this.rerunRequested && !this.abort) { this.rerunRequested = false; i--; continue; }
          break;
        }
        if (model.gates.some((g) => g.kind === "phase")) this.writeReports(model, true);
      }
    }
    this.stopProbes?.();
    const reason = this.budgetExceeded ? (this.budgetExceededMetric === "turns" ? "turns exceeded" : "budget exceeded") : this.abort ? "stopped by operator" : undefined;
    this.emitEv({ t: now(), kind: "run.end", runId: this.store.runId, ok, reason });
    this.emit("done", ok);
    return ok;
  }

  /** Blocks until the operator asks to re-run or quit after a failure. */
  waitForDecision(): Promise<"rerun" | "quit"> {
    if (this.budgetExceeded) return Promise.resolve("quit");
    return new Promise((resolve) => { this.once("decision", resolve); });
  }

  private async runOne(p: { id: string; prompt: string; plan?: PlanModel; evidenceDir?: string }) {
    const cfg = this.opts.config;
    const t0 = now();
    this.emitEv({ t: t0, kind: "plan.start", planId: p.id, file: p.plan?.file ?? "(prompt)", title: p.plan?.title ?? "prompt", gateIds: p.plan?.gates.map((g) => g.id) ?? [] });
    const session = new PlanSession({

    const session = new PlanSession({
      planId: p.id, plan: p.plan, prompt: p.prompt, cwd: this.opts.cwd, env: buildEnv(cfg), model: cfg.model, maxTurns: cfg.maxTurns, maxBudgetUsd: cfg.maxBudgetUsd,
      addDirs: cfg.addDirs, rails: cfg.rails, approvals: this.approvals, evidenceDir: p.evidenceDir, resumeSessionId: this.opts.resume, pathToClaudeCodeExecutable: resolveClaudeBin(this.opts.pathToClaudeCodeExecutable), settingSources: cfg.settingSources,
    });
    this.session = session;
    session.on("event", (ev: RunEvent) => {
      this.emitEv(ev);
      if (ev.kind === "session.result" && this.guard) {
        const signals = this.guard.observe({ planId: ev.planId, costUsd: ev.costUsd, turns: ev.turns });
        for (const s of signals) {
          if (s.type === "warn") {
            this.emitEv({ t: now(), kind: "budget.warn", runId: this.store.runId, metric: s.metric, thresholdPct: s.thresholdPct!, spent: s.spent, cap: s.cap, message: s.message });
          } else {
            this.emitEv({ t: now(), kind: "budget.exceeded", runId: this.store.runId, metric: s.metric, spent: s.spent, cap: s.cap, message: s.message });
            this.budgetExceeded = true;
            this.budgetExceededMetric = s.metric;
            this.abort = true;
            void this.session?.interrupt();
          }
        }
      }
    });
    session.on("approval", (req: ApprovalRequest) => this.emit("approval", req));
    session.on("gateApproval", (g: GateApproval) => this.emit("gateApproval", g));
    let result: { verdict: "pass" | "fail" | "halted"; reason?: string };
    try { result = await session.run(); } catch (e) { result = { verdict: "halted", reason: String((e as Error).message ?? e) }; }
    if (p.plan) for (const g of p.plan.gates) if (session.gateState.get(g.id) === "pending" && result.verdict !== "pass") { /* leave pending */ }
    this.emitEv({ t: now(), kind: "plan.end", planId: p.id, verdict: result.verdict, reason: result.reason, durationMs: now() - t0 });
    if (result.verdict !== "pass" && !this.abort) {
      const d = await this.waitForDecision();
      if (d === "rerun") this.rerunRequested = true; else this.abort = true;
    }
    this.session = null;
    return result;
  }

  decide(d: "rerun" | "quit") { this.emit("decision", d); }

  private writeReports(model: PlanModel, pass: boolean) {
    const phaseDir = dirname(model.file);
    const phaseGates = [...this.models.values()].filter((m) => m.phase === model.phase);
    const gates = phaseGates.flatMap((m) => this.store.gatesForPlan(m.id));
    const md = renderValidation(phaseGates, gates, { phase: model.phase, platform: model.platform, runId: this.store.runId, evidenceDir: `phases/${model.phase}/evidence` });
    const out = validationPath(phaseDir, model.phase);
    writeFileSync(out, md);
    const phaseNo = model.phase.split("-")[0];
    const roadmap = join(this.planRoot, "ROADMAP.md");
    const phaseGate = gates.find((g) => g.gateId.startsWith("VG-PHASE"));
    if (existsSync(roadmap)) updateRoadmapStatus(roadmap, phaseNo, pass ? "✓ Validated" : "✗ Failed", phaseGate ? `${phaseGate.gateId} ${phaseGate.verdict.toUpperCase()}` : `${model.id} ${pass ? "PASS" : "FAIL"}`, `runs/${this.store.runId}`);
    this.emitEv({ t: now(), kind: "log", level: "info", source: "vigil", message: `wrote ${out}${existsSync(roadmap) ? " · ROADMAP status updated" : ""}` });
  }
}

/** Reduces RunEvents into the UI state the cockpit renders. Pure; testable. */
import type { RunEvent, Verdict, TokenUsage } from "../engine/events.js";

export interface ToolCard { id: string; name: string; input: unknown; summary: string; startedAt: number; endedAt?: number; ok?: boolean; tail: string; output: string; parentId: string | null; }
export interface GateView { id: string; kind: string; verdict: Verdict; reason?: string; startedAt?: number; endedAt?: number; evidence: { path: string; present: boolean; bytes: number }[]; }
export interface PlanView { id: string; title: string; verdict: "pending" | "running" | "pass" | "fail" | "halted"; startedAt?: number; endedAt?: number; gates: GateView[]; }
export interface DiagRow { t: number; source: string; level: "debug" | "info" | "warn" | "error"; text: string; }
export interface StreamBlock { kind: "text" | "tool"; id: string; parentId: string | null; text?: string; }

export interface UIState {
  runId: string; label: string; model: string; baseUrl?: string; cwd: string; mode: "plan" | "prompt";
  startedAt: number; endedAt?: number; ok?: boolean; endReason?: string;
  plans: PlanView[]; activePlan?: string;
  stream: StreamBlock[]; tools: Record<string, ToolCard>; toolOrder: string[];
  toolCounts: Record<string, number>; latencies: number[];
  diag: DiagRow[];
  costUsd: number; usage: TokenUsage; turns: number; modelUsage: Record<string, { costUSD: number; inputTokens: number; outputTokens: number }>;
  /** Cumulative spend/turns across all plans in the run. */
  spentUsd: number; totalTurns: number;
  /** Budget cap (unset = no cap configured). */
  maxBudgetUsd?: number;
  /** Warn thresholds (percent) already emitted for cost. */
  budgetWarned: number[];
  /** Internal: last observed cost/turns per plan, to compute deltas. */
  planCosts: Record<string, number>; planTurns: Record<string, number>;
  pendingApproval?: { requestId: string; tool: string; input: unknown };
  paused: boolean; probes: Record<string, { ok: boolean; detail: string; t: number }>;
  hookCounts: { allow: number; deny: number; warn: number };
  sessionId?: string;
}

export const MAX_DIAG = 400;
export const MAX_STREAM = 600;

export function initialState(): UIState {
  return { runId: "", label: "", model: "", cwd: "", mode: "plan", startedAt: Date.now(), plans: [], stream: [], tools: {}, toolOrder: [], toolCounts: {}, latencies: [], diag: [], costUsd: 0, usage: { input: 0, output: 0, cacheRead: 0, cacheCreate: 0 }, turns: 0, modelUsage: {}, spentUsd: 0, totalTurns: 0, budgetWarned: [], planCosts: {}, planTurns: {}, paused: false, probes: {}, hookCounts: { allow: 0, deny: 0, warn: 0 } };
}

export function summarizeInput(name: string, input: unknown): string {
  const o = (input ?? {}) as Record<string, unknown>;
  const s = (v: unknown) => String(v ?? "").replace(/\s+/g, " ").trim();
  switch (name) {
    case "Bash": return s(o.command);
    case "Read": return `${s(o.file_path)}${o.offset ? ` (from line ${o.offset})` : ""}`;
    case "Write": return s(o.file_path);
    case "Edit": case "MultiEdit": return s(o.file_path);
    case "Grep": return `${s(o.pattern)} in ${s(o.path ?? ".")}`;
    case "Glob": return s(o.pattern);
    case "Agent": case "Task": return `${s(o.subagent_type ?? "agent")}: ${s(o.description ?? o.prompt).slice(0, 80)}`;
    default: return JSON.stringify(o).slice(0, 120);
  }
}

function diag(state: UIState, row: DiagRow) { state.diag.push(row); if (state.diag.length > MAX_DIAG) state.diag.splice(0, state.diag.length - MAX_DIAG); }

export function reduce(prev: UIState, ev: RunEvent): UIState {
  const s: UIState = { ...prev };
  switch (ev.kind) {
    case "run.start": Object.assign(s, { runId: ev.runId, label: ev.label, model: ev.model, baseUrl: ev.baseUrl, cwd: ev.cwd, mode: ev.mode, startedAt: ev.t }); break;
    case "run.end": s.endedAt = ev.t; s.ok = ev.ok; s.endReason = ev.reason; break;
    case "plan.start": {
      s.plans = s.plans.map((p) => p.id === ev.planId ? { ...p, verdict: "running", startedAt: ev.t } : p);
      if (!s.plans.some((p) => p.id === ev.planId)) s.plans = [...s.plans, { id: ev.planId, title: ev.title ?? ev.file, verdict: "running", startedAt: ev.t, gates: ev.gateIds.map((id) => ({ id, kind: id.includes("PHASE") ? "phase" : id.includes("REGRESS") ? "regression" : "validation", verdict: "pending", evidence: [] })) }];
      s.activePlan = ev.planId; s.stream = []; s.toolOrder = []; s.tools = {}; s.toolCounts = {}; s.latencies = [];
      diag(s, { t: ev.t, source: "plan", level: "info", text: `▶ ${ev.planId} started (${ev.gateIds.length} gates)` });
      break;
    }
    case "plan.end": s.plans = s.plans.map((p) => p.id === ev.planId ? { ...p, verdict: ev.verdict, endedAt: ev.t } : p); diag(s, { t: ev.t, source: "plan", level: ev.verdict === "pass" ? "info" : "error", text: `${ev.verdict === "pass" ? "✓" : "✗"} ${ev.planId} ${ev.verdict}${ev.reason ? " — " + ev.reason : ""}` }); break;
    case "session.init": s.sessionId = ev.sessionId; s.model = ev.model || s.model; diag(s, { t: ev.t, source: "sdk", level: "info", text: `session ${ev.sessionId.slice(0, 8)} · ${ev.model} · ${ev.tools.length} tools · cwd ${ev.cwd}` }); break;
    case "session.result": {
      // session.result reports the session's cumulative cost/turns; accumulate run-level totals via per-plan deltas.
      const prevCost = s.planCosts[ev.planId] ?? 0;
      const prevTurns = s.planTurns[ev.planId] ?? 0;
      s.planCosts = { ...s.planCosts, [ev.planId]: ev.costUsd };
      s.planTurns = { ...s.planTurns, [ev.planId]: ev.turns };
      s.spentUsd = s.spentUsd + (ev.costUsd - prevCost);
      s.totalTurns = s.totalTurns + (ev.turns - prevTurns);
      s.costUsd = ev.costUsd; s.usage = ev.usage; s.turns = ev.turns; s.modelUsage = ev.modelUsage;
      diag(s, { t: ev.t, source: "sdk", level: "info", text: `result/${ev.subtype} · ${ev.turns} turns · $${ev.costUsd.toFixed(3)} · ${(ev.durationMs / 1000).toFixed(0)}s` });
      break;
    }
    case "budget.warn":
      s.budgetWarned = s.budgetWarned.includes(ev.thresholdPct) ? s.budgetWarned : [...s.budgetWarned, ev.thresholdPct];
      diag(s, { t: ev.t, source: "budget", level: "warn", text: ev.message });
      break;
    case "budget.exceeded":
      diag(s, { t: ev.t, source: "budget", level: "error", text: ev.message });
      break;
    case "assistant.delta": {
      const last = s.stream[s.stream.length - 1];
      if (last && last.kind === "text" && last.parentId === ev.parentToolUseId && !last.id.startsWith("final")) { s.stream = [...s.stream.slice(0, -1), { ...last, text: (last.text ?? "") + ev.text }]; }
      else s.stream = [...s.stream, { kind: "text", id: `d${ev.t}${Math.random().toString(36).slice(2, 6)}`, parentId: ev.parentToolUseId, text: ev.text }];
      break;
    }
    case "assistant.text": {
      // replace the streamed draft (if any) with the final text
      const last = s.stream[s.stream.length - 1];
      if (last && last.kind === "text" && last.parentId === ev.parentToolUseId && !last.id.startsWith("final")) s.stream = [...s.stream.slice(0, -1), { kind: "text", id: `final${ev.t}`, parentId: ev.parentToolUseId, text: ev.text }];
      else s.stream = [...s.stream, { kind: "text", id: `final${ev.t}${Math.random().toString(36).slice(2, 6)}`, parentId: ev.parentToolUseId, text: ev.text }];
      break;
    }
    case "tool.start": {
      const card: ToolCard = { id: ev.toolUseId, name: ev.name, input: ev.input, summary: summarizeInput(ev.name, ev.input), startedAt: ev.t, tail: "", output: "", parentId: ev.parentToolUseId };
      s.tools = { ...s.tools, [ev.toolUseId]: card }; s.toolOrder = [...s.toolOrder, ev.toolUseId];
      s.toolCounts = { ...s.toolCounts, [ev.name]: (s.toolCounts[ev.name] ?? 0) + 1 };
      s.stream = [...s.stream, { kind: "tool", id: ev.toolUseId, parentId: ev.parentToolUseId }];
      break;
    }
    case "tool.output": { const c = s.tools[ev.toolUseId]; if (c) s.tools = { ...s.tools, [ev.toolUseId]: { ...c, output: (c.output + ev.chunk).slice(-200000), tail: (c.tail + ev.chunk).split("\n").slice(-6).join("\n").slice(-600) } }; break; }
    case "tool.end": { const c = s.tools[ev.toolUseId]; if (c) { s.tools = { ...s.tools, [ev.toolUseId]: { ...c, endedAt: ev.t, ok: ev.ok, output: c.output || ev.output } }; s.latencies = [...s.latencies, ev.durationMs].slice(-60); } break; }
    case "hook": {
      s.hookCounts = { ...s.hookCounts, [ev.decision === "observe" ? "allow" : ev.decision]: s.hookCounts[ev.decision === "observe" ? "allow" : ev.decision] + (ev.decision === "observe" ? 0 : 1) };
      if (ev.decision !== "observe") diag(s, { t: ev.t, source: "hook", level: ev.decision === "deny" ? "error" : ev.decision === "warn" ? "warn" : "debug", text: `${ev.event} ${ev.tool ?? ""} ${ev.decision}${ev.reason ? " — " + ev.reason : ""}` });
      break;
    }
    case "gate.update": {
      s.plans = s.plans.map((p) => p.id !== ev.planId ? p : { ...p, gates: p.gates.map((g) => g.id === ev.gateId ? { ...g, verdict: ev.verdict, reason: ev.reason, evidence: ev.evidence ?? g.evidence, startedAt: g.startedAt ?? ev.t, endedAt: ev.verdict === "pass" || ev.verdict === "fail" ? ev.t : g.endedAt } : g) });
      diag(s, { t: ev.t, source: "gate", level: ev.verdict === "fail" ? "error" : "info", text: `${ev.gateId} → ${ev.verdict.toUpperCase()}${ev.reason ? " — " + ev.reason : ""}${ev.evidence?.length ? ` · evidence ${ev.evidence.filter((e) => e.present).length}/${ev.evidence.length}` : ""}` });
