function GateRow({ g, tick, animate, width }: { g: GateView; tick: number; animate: boolean; width: number }) {
  const { icon, color } = verdictIcon(g.verdict === "pending" ? "pending" : g.verdict === "running" ? "running" : g.verdict, tick, animate);
  const dur = g.startedAt ? fmtDuration((g.endedAt ?? Date.now()) - g.startedAt) : "";
  const present = g.evidence.filter((e) => e.present).length;
  return (
    <Box flexDirection="column">
      <Box>
        <Text color={color}>  {icon} </Text>
        <Text color={g.verdict === "pending" ? C.dim : C.text}>{truncate(g.id, width - 18).padEnd(Math.max(0, width - 18))}</Text>
        <Text color={C.dim}>{dur.padStart(6)}</Text>
