import React from "react";
import { Box, Text } from "ink";
import type { UIState, ToolCard, GateView, PlanView, DiagRow } from "../state/reducer.js";
import { spinner, sparkline, progressBar, fmtDuration, fmtElapsed, fmtTokens, fadeLevel, truncate, clockHHMMSS, PULSE } from "./anim.js";

export const C = { accent: "#7aa2f7", ok: "#9ece6a", bad: "#f7768e", warn: "#e0af68", dim: "#565f89", text: "#c0caf5", muted: "#9aa5ce", tool: "#bb9af7", frame: "#3b4261" } as const;

function verdictIcon(v: string, tick: number, animate: boolean): { icon: string; color: string } {
  switch (v) {
    case "pass": return { icon: animate ? PULSE[tick % PULSE.length] : "✓", color: C.ok };
    case "fail": case "halted": return { icon: "✗", color: C.bad };
    case "running": return { icon: animate ? spinner(tick) : "▶", color: C.accent };
    case "skipped": return { icon: "↷", color: C.warn };
    default: return { icon: "○", color: C.dim };
  }
}

export function Header({ s, tick, animate, width }: { s: UIState; tick: number; animate: boolean; width: number }) {
  const elapsed = (s.endedAt ?? Date.now()) - s.startedAt;
  const live = s.endedAt ? (s.ok ? "done" : "halted") : "live";
  const liveColor = s.endedAt ? (s.ok ? C.ok : C.bad) : C.ok;
  const plansDone = s.plans.filter((p) => p.verdict === "pass").length;
  const gatesAll = s.plans.flatMap((p) => p.gates);
  const gatesDone = gatesAll.filter((g) => g.verdict === "pass").length;
  const frac = gatesAll.length ? gatesDone / gatesAll.length : 0;
  const cacheTotal = s.usage.input + s.usage.cacheRead + s.usage.cacheCreate;
  const cachePct = cacheTotal ? Math.round((s.usage.cacheRead / cacheTotal) * 100) : 0;
  const barW = Math.max(10, Math.min(40, width - 100));
  return (
    <Box flexDirection="column" borderStyle="round" borderColor={C.frame} paddingX={1}>
      <Box>
        <Text bold color={C.accent}>VIGIL</Text>
        <Text color={C.muted}>  {s.label}</Text>
        {s.activePlan && <Text color={C.text}>  ▶ {s.activePlan}</Text>}
        <Text>  </Text>
        <Text color={liveColor}>{animate && !s.endedAt ? (tick % 2 ? "●" : "○") : "●"} {live} {fmtDuration(elapsed)}</Text>
        <Text color={C.dim}>  {s.model}{s.baseUrl ? ` via ${s.baseUrl.replace(/^https?:\/\//, "")}` : ""}</Text>
        {s.paused && <Text color={C.warn}>  ⏸ PAUSED</Text>}
      </Box>
      <Box>
        <Text color={C.accent}>{progressBar(frac, barW)}</Text>
        <Text color={C.muted}>  plan {plansDone}/{s.plans.length} · gates {gatesDone}/{gatesAll.length} · turn {s.turns} · </Text>
        <Text color={C.ok}>${s.costUsd.toFixed(2)}</Text>
        <Text color={C.muted}> · {fmtTokens(s.usage.input + s.usage.cacheRead)} in / {fmtTokens(s.usage.output)} out · cache {cachePct}%</Text>
        <Text color={C.dim}> · rails ✓{s.hookCounts.allow} ⚠{s.hookCounts.warn} ✗{s.hookCounts.deny}</Text>
      </Box>
    </Box>
  );
}

