import type { RunEvent } from "../src/engine/events.js";

const PLAN = `# P\n<task id="1">\nName: t\n</task>\n<validation_gate id="VG-1" blocking="true">\nCapture: \`E/vg1-a.txt\`, \`E/vg1-b.txt\`\nPass criteria: both present\n</validation_gate>\n`;

function mk(evidenceDir: string, approvals: "auto" | "gates" = "auto") {
  const plan = parsePlan(PLAN, "/x/phases/01-p/01-01-PLAN.md");
  const s = new PlanSession({ planId: "01-01", plan, prompt: "", cwd: "/", env: {}, model: "m", maxTurns: 1, addDirs: [], rails: [], approvals, evidenceDir });
  const events: RunEvent[] = [];
  s.on("event", (e: RunEvent) => events.push(e));
  return { s, events, plan };
}

describe("PlanSession verdict + evidence enforcement (no SDK)", () => {
  it("downgrades a claimed PASS to FAIL when evidence is missing, and injects a correction", async () => {
    const dir = mkdtempSync(join(tmpdir(), "vg-"));
    writeFileSync(join(dir, "vg1-a.txt"), "ok");
    const { s, events } = mk(dir);
    await (s as unknown as { onVerdictLine: (l: string) => Promise<void> }).onVerdictLine("VG-1: PASS");
    const g = events.find((e) => e.kind === "gate.update") as Extract<RunEvent, { kind: "gate.update" }>;
    expect(g.verdict).toBe("fail");
    expect(g.reason).toMatch(/vg1-b\.txt/);
    expect(g.evidence).toEqual([{ path: "vg1-a.txt", present: true, bytes: 2 }, { path: "vg1-b.txt", present: false, bytes: 0 }]);
    expect(events.some((e) => e.kind === "control" && e.action === "inject" && /vg1-b\.txt/.test(e.detail ?? ""))).toBe(true);
    expect(s.gateState.get("VG-1")).toBe("fail");
  });
  it("accepts PASS once all evidence exists and records plan verdict", async () => {
    const dir = mkdtempSync(join(tmpdir(), "vg-"));
    writeFileSync(join(dir, "vg1-a.txt"), "ok"); writeFileSync(join(dir, "vg1-b.txt"), "ok");
    const { s, events } = mk(dir);
    const call = (s as unknown as { onVerdictLine: (l: string) => Promise<void> }).onVerdictLine.bind(s);
    await call("**VG-1: PASS**");
    await call("PLAN 01-01: PASS");
    expect(s.gateState.get("VG-1")).toBe("pass");
    expect(s.planVerdict).toBe("pass");
    expect(events.filter((e) => e.kind === "gate.update")).toHaveLength(1);
  });
  it("in gates mode asks the operator and honours a rejection", async () => {
    const dir = mkdtempSync(join(tmpdir(), "vg-"));
    writeFileSync(join(dir, "vg1-a.txt"), "ok"); writeFileSync(join(dir, "vg1-b.txt"), "ok");
    const { s } = mk(dir, "gates");
    s.on("gateApproval", (g: { gateId: string; resolve: (a: boolean) => void }) => { expect(g.gateId).toBe("VG-1"); g.resolve(false); });
    await (s as unknown as { onVerdictLine: (l: string) => Promise<void> }).onVerdictLine("VG-1: PASS");
    expect(s.gateState.get("VG-1")).toBe("fail");
  });
  it("dedupes an identical verdict line seen twice within a turn", async () => {
    const dir = mkdtempSync(join(tmpdir(), "vg-"));
    writeFileSync(join(dir, "vg1-a.txt"), "ok"); writeFileSync(join(dir, "vg1-b.txt"), "ok");
    const { s, events } = mk(dir);
    const once = (s as unknown as { onVerdictLineOnce: (l: string) => Promise<void> }).onVerdictLineOnce.bind(s);
    await once("VG-1: PASS"); await once("`VG-1: PASS`");
    expect(events.filter((e) => e.kind === "gate.update")).toHaveLength(1);
  });
});
