/** Reduces RunEvents into the UI state the cockpit renders. Pure; testable. */
import type { RunEvent, Verdict, TokenUsage } from "../engine/events.js";

export interface ToolCard { id: string; name: string; input: unknown; summary: string; startedAt: number; endedAt?: number; ok?: boolean; tail: string; output: string; parentId: string | null; }
export interface GateView { id: string; kind: string; verdict: Verdict; reason?: string; startedAt?: number; endedAt?: number; evidence: { path: string; present: boolean; bytes: number }[]; }
export interface PlanView { id: string; title: string; verdict: "pending" | "running" | "pass" | "fail" | "halted"; startedAt?: number; endedAt?: number; gates: GateView[]; }
export interface DiagRow { t: number; source: string; level: "debug" | "info" | "warn" | "error"; text: string; }
export interface StreamBlock { kind: "text" | "tool"; id: string; parentId: string | null; text?: string; }

export interface UIState {
  runId: string; label: string; model: string; baseUrl?: string; cwd: string; mode: "plan" | "prompt";
  startedAt: number; endedAt?: number; ok?: boolean; endReason?: string;
  plans: PlanView[]; activePlan?: string;
  stream: StreamBlock[]; tools: Record<string, ToolCard>; toolOrder: string[];
  toolCounts: Record<string, number>; latencies: number[];
  diag: DiagRow[];
  costUsd: number; usage: TokenUsage; turns: number; modelUsage: Record<string, { costUSD: number; inputTokens: number; outputTokens: number }>;
  /** Cumulative spend/turns across all plans in the run. */
  spentUsd: number; totalTurns: number;
  /** Budget cap (unset = no cap configured). */
  maxBudgetUsd?: number;
  /** Turn cap (unset = no cap configured). */
  maxTurns?: number;
  /** Warn thresholds (percent) already emitted for cost. */
  budgetWarned: number[];
  /** Internal: last observed cost/turns per plan, to compute deltas. */
  planCosts: Record<string, number>; planTurns: Record<string, number>;
  pendingApproval?: { requestId: string; tool: string; input: unknown };
  paused: boolean; probes: Record<string, { ok: boolean; detail: string; t: number }>;
  hookCounts: { allow: number; deny: number; warn: number };
  sessionId?: string;
}

export const MAX_DIAG = 400;
export const MAX_STREAM = 600;

export function initialState(): UIState {
  return { runId: "", label: "", model: "", cwd: "", mode: "plan", startedAt: Date.now(), plans: [], stream: [], tools: {}, toolOrder: [], toolCounts: {}, latencies: [], diag: [], costUsd: 0, usage: { input: 0, output: 0, cacheRead: 0, cacheCreate: 0 }, turns: 0, modelUsage: {}, spentUsd: 0, totalTurns: 0, budgetWarned: [], planCosts: {}, planTurns: {}, paused: false, probes: {}, hookCounts: { allow: 0, deny: 0, warn: 0 } };
}

export function summarizeInput(name: string, input: unknown): string {
  const o = (input ?? {}) as Record<string, unknown>;
  const s = (v: unknown) => String(v ?? "").replace(/\s+/g, " ").trim();
  switch (name) {
    case "Bash": return s(o.command);
    case "Read": return `${s(o.file_path)}${o.offset ? ` (from line ${o.offset})` : ""}`;
    case "Write": return s(o.file_path);
    case "Edit": case "MultiEdit": return s(o.file_path);
    case "Grep": return `${s(o.pattern)} in ${s(o.path ?? ".")}`;
    case "Glob": return s(o.pattern);
    case "Agent": case "Task": return `${s(o.subagent_type ?? "agent")}: ${s(o.description ?? o.prompt).slice(0, 80)}`;
    default: return JSON.stringify(o).slice(0, 120);
  }
}

function diag(state: UIState, row: DiagRow) { state.diag.push(row); if (state.diag.length > MAX_DIAG) state.diag.splice(0, state.diag.length - MAX_DIAG); }

export function reduce(prev: UIState, ev: RunEvent): UIState {
  const s: UIState = { ...prev };
  switch (ev.kind) {
    case "run.start": Object.assign(s, { runId: ev.runId, label: ev.label, model: ev.model, baseUrl: ev.baseUrl, cwd: ev.cwd, mode: ev.mode, startedAt: ev.t, maxBudgetUsd: ev.maxBudgetUsd, maxTurns: ev.maxTurns }); break;
    case "run.end": s.endedAt = ev.t; s.ok = ev.ok; s.endReason = ev.reason; break;
    case "plan.start": {
      s.plans = s.plans.map((p) => p.id === ev.planId ? { ...p, verdict: "running", startedAt: ev.t } : p);
      if (!s.plans.some((p) => p.id === ev.planId)) s.plans = [...s.plans, { id: ev.planId, title: ev.title ?? ev.file, verdict: "running", startedAt: ev.t, gates: ev.gateIds.map((id) => ({ id, kind: id.includes("PHASE") ? "phase" : id.includes("REGRESS") ? "regression" : "validation", verdict: "pending", evidence: [] })) }];
      s.activePlan = ev.planId; s.stream = []; s.toolOrder = []; s.tools = {}; s.toolCounts = {}; s.latencies = [];
      diag(s, { t: ev.t, source: "plan", level: "info", text: `▶ ${ev.planId} started (${ev.gateIds.length} gates)` });
      break;
    }
    case "plan.end": s.plans = s.plans.map((p) => p.id === ev.planId ? { ...p, verdict: ev.verdict, endedAt: ev.t } : p); diag(s, { t: ev.t, source: "plan", level: ev.verdict === "pass" ? "info" : "error", text: `${ev.verdict === "pass" ? "✓" : "✗"} ${ev.planId} ${ev.verdict}${ev.reason ? " — " + ev.reason : ""}` }); break;
    case "session.init": s.sessionId = ev.sessionId; s.model = ev.model || s.model; diag(s, { t: ev.t, source: "sdk", level: "info", text: `session ${ev.sessionId.slice(0, 8)} · ${ev.model} · ${ev.tools.length} tools · cwd ${ev.cwd}` }); break;
    case "session.result": {
      // session.result reports the session's cumulative cost/turns; accumulate run-level totals via per-plan deltas.
      const prevCost = s.planCosts[ev.planId] ?? 0;
      const prevTurns = s.planTurns[ev.planId] ?? 0;
      s.planCosts = { ...s.planCosts, [ev.planId]: ev.costUsd };
      s.planTurns = { ...s.planTurns, [ev.planId]: ev.turns };
      s.spentUsd = s.spentUsd + (ev.costUsd - prevCost);
      s.totalTurns = s.totalTurns + (ev.turns - prevTurns);
      s.costUsd = ev.costUsd; s.usage = ev.usage; s.turns = ev.turns; s.modelUsage = ev.modelUsage;
      diag(s, { t: ev.t, source: "sdk", level: "info", text: `result/${ev.subtype} · ${ev.turns} turns · $${ev.costUsd.toFixed(3)} · ${(ev.durationMs / 1000).toFixed(0)}s` });
      break;
    }
    case "budget.warn":
      s.budgetWarned = s.budgetWarned.includes(ev.thresholdPct) ? s.budgetWarned : [...s.budgetWarned, ev.thresholdPct];
      diag(s, { t: ev.t, source: "budget", level: "warn", text: ev.message });
      break;
    case "budget.exceeded":
      diag(s, { t: ev.t, source: "budget", level: "error", text: ev.message });
      break;
    case "assistant.delta": {
      const last = s.stream[s.stream.length - 1];
      if (last && last.kind === "text" && last.parentId === ev.parentToolUseId && !last.id.startsWith("final")) { s.stream = [...s.stream.slice(0, -1), { ...last, text: (last.text ?? "") + ev.text }]; }
      else s.stream = [...s.stream, { kind: "text", id: `d${ev.t}${Math.random().toString(36).slice(2, 6)}`, parentId: ev.parentToolUseId, text: ev.text }];
      break;
    }
    case "assistant.text": {
