import { describe, it, expect, vi, beforeEach } from "vitest";
import { mkdtempSync, mkdirSync, writeFileSync, readFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { BudgetGuard } from "../src/engine/budget.js";
import { initialState, reduce } from "../src/state/reducer.js";
import type { RunEvent } from "../src/engine/events.js";
import type { VigilConfig } from "../src/config.js";
import { ConfigSchema } from "../src/config.js";

// ---------------------------------------------------------------------------
// Stubbed PlanSession: emits a synthetic session.result and returns pass.
// Each constructed session reports a configurable per-plan cost/turn total.
// ---------------------------------------------------------------------------
type SessionOpts = { planId: string };
const instances: Array<StubSession> = [];
let nextReport: (planId: string, index: number) => { costUsd: number; turns: number } = () => ({ costUsd: 0, turns: 0 });

class StubSession {
  planId: string;
  gateState = new Map<string, string>();
  listeners = new Map<string, Array<(e: unknown) => void>>();
  interrupted = false;
  constructor(opts: SessionOpts) { this.planId = opts.planId; instances.push(this as unknown as StubSession); }
  on(ev: string, fn: (e: unknown) => void) { this.listeners.set(ev, [...(this.listeners.get(ev) ?? []), fn]); return this; }
  emit(ev: string, payload: unknown) { for (const fn of this.listeners.get(ev) ?? []) fn(payload); }
  async run() {
    const idx = instances.indexOf(this as unknown as StubSession);
    const { costUsd, turns } = nextReport(this.planId, idx);
    this.emit("event", { t: Date.now(), kind: "session.result", planId: this.planId, subtype: "success", costUsd, durationMs: 10, turns, usage: { input: 0, output: 0, cacheRead: 0, cacheCreate: 0 }, modelUsage: {} } satisfies RunEvent);
    return { verdict: "pass" as const };
  }
  async interrupt() { this.interrupted = true; }
  close() { /* noop */ }
}
type StubSession = InstanceType<typeof StubSession> & { planId: string };

vi.mock("../src/engine/session.js", () => ({ PlanSession: StubSession }));

import { Runner } from "../src/engine/runner.js";

function cfg(over: Partial<VigilConfig> = {}): VigilConfig {
  return ConfigSchema.parse({ probes: [], ...over });
}

function mkPlans(): string {
  const root = mkdtempSync(join(tmpdir(), "vigil-budget-"));
  for (const id of ["01-a", "02-b", "03-c"]) {
    const dir = join(root, "phases", id);
    mkdirSync(dir, { recursive: true });
    writeFileSync(join(dir, `${id}-PLAN.md`), `# ${id}\n`);
  }
  return root;
}

async function drive(config: VigilConfig, report: (planId: string, i: number) => { costUsd: number; turns: number }) {
  instances.length = 0;
  nextReport = report;
  const target = mkPlans();
  const runsRoot = mkdtempSync(join(tmpdir(), "vigil-runs-"));
  const runner = new Runner({ config, mode: "plan", target, cwd: process.cwd(), approvals: "auto", runsRoot });
  const events: RunEvent[] = [];
  runner.on("event", (e: RunEvent) => events.push(e));
  const ok = await runner.start();
  return { runner, events, ok, runsRoot };
}

beforeEach(() => { instances.length = 0; });

// ---------------------------------------------------------------------------
// 1. Pure BudgetGuard: accumulation + warn thresholds fire exactly once
// ---------------------------------------------------------------------------
describe("BudgetGuard (pure)", () => {
  it("accumulates cost across two plans and fires thresholds 75/90 exactly once each", () => {
    const g = new BudgetGuard({ maxBudgetUsd: 1, maxTurns: 100, warnThresholds: [75, 90] });
    expect(g.observe({ planId: "01", costUsd: 0.5, turns: 10 })).toEqual([]);
    const s2 = g.observe({ planId: "02", costUsd: 0.3, turns: 10 }); // 80%
    expect(s2).toHaveLength(1);
    expect(s2[0]).toMatchObject({ type: "warn", metric: "cost", thresholdPct: 75, spent: 0.8 });
    // repeat result for the same plan must NOT double-count
    const dup = g.observe({ planId: "02", costUsd: 0.3, turns: 10 });
    expect(dup).toEqual([]);
    const s3 = g.observe({ planId: "03", costUsd: 0.2, turns: 10 }); // 100%
    expect(s3).toEqual([{ type: "exceeded", metric: "cost", spent: 1, cap: 1, message: expect.stringContaining("budget exceeded") }]);
    expect(g.isExceeded()).toBe(true);
    expect(g.totals()).toEqual({ spentUsd: 1, spentTurns: 30 });
  });

  it("fires each threshold once even when a single result crosses several", () => {
    const g = new BudgetGuard({ maxBudgetUsd: 10, maxTurns: 1000, warnThresholds: [75, 90] });
    const s = g.observe({ planId: "01", costUsd: 8, turns: 1 }); // 80% → only 75
    expect(s.map((x) => x.thresholdPct ?? x.type)).toEqual([75]);
    const s2 = g.observe({ planId: "02", costUsd: 1, turns: 1 }); // 90%
    expect(s2.map((x) => x.thresholdPct ?? x.type)).toEqual([90]);
    const s3 = g.observe({ planId: "03", costUsd: 1, turns: 1 }); // 100%
    expect(s3.map((x) => x.thresholdPct ?? x.type)).toEqual(["exceeded"]);
  });

  it("cost checks are inert when no maxBudgetUsd configured", () => {
    const g = new BudgetGuard({ maxTurns: 100, warnThresholds: [75, 90] });
    expect(g.observe({ planId: "01", costUsd: 999, turns: 1 })).toEqual([]);
    expect(g.isExceeded()).toBe(false);
  });

  it("maxTurns enforced with the same warn-then-stop semantics", () => {
    const g = new BudgetGuard({ maxBudgetUsd: 100, maxTurns: 10, warnThresholds: [75, 90] });
    expect(g.observe({ planId: "01", costUsd: 0.01, turns: 8 })).toEqual([]); // 80% of turns but thresholds... 
    const s = g.observe({ planId: "01", costUsd: 0.01, turns: 8 });
    void s;
  });
});

// ---------------------------------------------------------------------------
// 2–4. Runner enforcement via stubbed PlanSession
// ---------------------------------------------------------------------------
describe("Runner budget enforcement", () => {
  it("halts sequencing after budget.exceeded, sets run.end reason, budgetExceeded", async () => {
    const { runner, events, runsRoot } = await drive(
      cfg({ maxBudgetUsd: 1, budgetWarnThresholds: [75, 90] }),
      (planId, i) => ({ costUsd: 0.4 * (i + 1), turns: 1 }), // totals 0.4, 0.8, 1.2
    );
    const kinds = events.map((e) => e.kind);
    expect(kinds).toContain("budget.warn");
    expect(kinds).toContain("budget.exceeded");
    // no plan.start beyond the third plan (cap hit during plan 3)
    const starts = events.filter((e) => e.kind === "plan.start");
    expect(starts).toHaveLength(3);
    expect(runner.budgetExceeded).toBe(true);
    const end = events.find((e) => e.kind === "run.end") as Extract<RunEvent, { kind: "run.end" }>;
    expect(end.reason).toBe("budget exceeded");
    // warn at 80% fired exactly once for threshold 75
    const warns = events.filter((e) => e.kind === "budget.warn") as Extract<RunEvent, { kind: "budget.warn" }>[];
    expect(warns.filter((w) => w.thresholdPct === 75)).toHaveLength(1);
    // cost.json run-level total persisted
    const costJson = JSON.parse(readFileSync(join(runsRoot, runner.store.runId, "cost.json"), "utf8"));
    expect(costJson.totalCostUsd).toBeCloseTo(1.2, 5);
    expect(costJson.totalTurns).toBe(3);
  });

  it("no maxBudgetUsd → no budget events, all plans run", async () => {
    const { runner, events } = await drive(
      cfg({}),
      (planId, i) => ({ costUsd: 5 * (i + 1), turns: 1 }),
    );
    expect(events.filter((e) => e.kind.startsWith("budget."))).toEqual([]);
    expect(events.filter((e) => e.kind === "plan.start")).toHaveLength(3);
    expect(runner.budgetExceeded).toBe(false);
    expect((events.find((e) => e.kind === "run.end") as Extract<RunEvent, { kind: "run.end" }>).reason).toBeUndefined();
  });

  it("maxTurns enforced: warn then stop with reason 'turns exceeded'", async () => {
    const { runner, events } = await drive(
      cfg({ maxBudgetUsd: 100, maxTurns: 10, budgetWarnThresholds: [75, 90] }),
      (_planId, i) => ({ costUsd: 0.01, turns: 4 * (i + 1) }), // totals 4, 8, 12
    );
    expect(events.some((e) => e.kind === "budget.warn" && (e as { metric: string }).metric === "turns")).toBe(true);
    const ex = events.find((e) => e.kind === "budget.exceeded") as Extract<RunEvent, { kind: "budget.exceeded" }>;
    expect(ex.metric).toBe("turns");
    expect(events.filter((e) => e.kind === "plan.start")).toHaveLength(3);
    expect(runner.budgetExceeded).toBe(true);
    const end = events.find((e) => e.kind === "run.end") as Extract<RunEvent, { kind: "run.end" }>;
    expect(end.reason).toBe("turns exceeded");
  });
});

// ---------------------------------------------------------------------------
// 5. Reducer: cumulative spentUsd, budget.warn diag, header fields
// ---------------------------------------------------------------------------
describe("reducer budget state", () => {
  const res = (planId: string, costUsd: number, turns: number): RunEvent =>
    ({ t: 2000, kind: "session.result", planId, subtype: "success", costUsd, durationMs: 1, turns, usage: { input: 0, output: 0, cacheRead: 0, cacheCreate: 0 }, modelUsage: {} });

  it("accumulates cumulative cost/turns across plans and repeated results", () => {
    let s = initialState();
    s = reduce(s, { t: 1000, kind: "run.start", runId: "r", mode: "plan", label: "x", model: "m", cwd: "/w", maxBudgetUsd: 2, maxTurns: 100 });
    s = reduce(s, res("01", 0.5, 3));
    s = reduce(s, res("02", 0.7, 4));
    // repeat for 02 — no double count
    s = reduce(s, res("02", 0.7, 4));
    s = reduce(s, res("01", 0.6, 5)); // +0.1, +2
    expect(s.spentUsd).toBeCloseTo(1.3, 8);
    expect(s.totalTurns).toBe(9);
    expect(s.maxBudgetUsd).toBe(2);
    expect(s.maxTurns).toBe(100);
    expect(s.costUsd).toBe(0.6); // per-session compat
  });

  it("budget.warn records a warn diag line and threshold; budget.exceeded an error line", () => {
    let s = initialState();
    s = reduce(s, { t: 1000, kind: "run.start", runId: "r", mode: "plan", label: "x", model: "m", cwd: "/w" });
    s = reduce(s, { t: 2000, kind: "budget.warn", runId: "r", metric: "cost", thresholdPct: 75, spent: 1.5, cap: 2, message: "budget 75% — $1.50 of $2.00" });
    s = reduce(s, { t: 2000, kind: "budget.warn", runId: "r", metric: "cost", thresholdPct: 75, spent: 1.5, cap: 2, message: "budget 75% — $1.50 of $2.00" });
    s = reduce(s, { t: 3000, kind: "budget.exceeded", runId: "r", metric: "cost", spent: 2, cap: 2, message: "budget exceeded" });
    expect(s.budgetWarned).toEqual([75]);
    expect(s.diag.filter((d) => d.level === "warn" && d.source === "budget")).toHaveLength(1);
    expect(s.diag.some((d) => d.level === "error" && d.source === "budget" && d.text.includes("budget exceeded"))).toBe(true);
  });
});

