  1	/**
  2	 * BudgetGuard — pure cumulative cost/turn tracking across session.result events.
  3	 *
  4	 * A session.result reports the total cost/turns for that plan's session; on
  5	 * repeat results for the same planId only the delta is counted, so cumulative
  6	 * spend equals the sum of per-plan session totals.
  7	 */
  8	
  9	export type BudgetMetric = "cost" | "turns";
 10	
 11	export interface BudgetSignal {
 12	  type: "warn" | "exceeded";
 13	  metric: BudgetMetric;
 14	  thresholdPct?: number; // warn only
 15	  spent: number;
 16	  cap: number;
 17	  message: string;
 18	}
 19	
 20	export interface BudgetGuardOpts {
 21	  maxBudgetUsd?: number;
 22	  maxTurns: number;
 23	  warnThresholds: number[]; // ascending percentages, e.g. [75, 90]
 24	}
 25	
 26	export interface SessionResultLike {
 27	  planId: string;
 28	  costUsd: number;
 29	  turns: number;
 30	}
 31	
 32	export class BudgetGuard {
 33	  private readonly opts: BudgetGuardOpts;
 34	  private readonly planCosts = new Map<string, number>();
 35	  private readonly planTurns = new Map<string, number>();
 36	  private readonly warned = { cost: new Set<number>(), turns: new Set<number>() };
 37	  private spentUsd = 0;
 38	  private spentTurns = 0;
 39	  private exceeded = false;
 40	
 41	  constructor(opts: BudgetGuardOpts) {
 42	    this.opts = opts;
 43	  }
 44	
 45	  /** Cumulative spend/turns so far. */
 46	  totals(): { spentUsd: number; spentTurns: number } {
 47	    return { spentUsd: this.spentUsd, spentTurns: this.spentTurns };
 48	  }
 49	
 50	  isExceeded(): boolean {
 51	    return this.exceeded;
 52	  }
 53	
 54	  /**
 55	   * Observe a session.result; returns warn signals (each threshold at most
 56	   * once per metric) and at most one exceeded signal when a cap is reached.
 57	   */
 58	  observe(result: SessionResultLike): BudgetSignal[] {
 59	    const prevCost = this.planCosts.get(result.planId) ?? 0;
 60	    const prevTurns = this.planTurns.get(result.planId) ?? 0;
 61	    const dCost = result.costUsd - prevCost;
 62	    const dTurns = result.turns - prevTurns;
 63	    if (dCost > 0) this.spentUsd += dCost;
 64	    if (dTurns > 0) this.spentTurns += dTurns;
 65	    this.planCosts.set(result.planId, result.costUsd);
 66	    this.planTurns.set(result.planId, result.turns);
 67	
 68	    const signals: BudgetSignal[] = [];
 69	
 70	    // cost checks inert when no cap configured
 71	    if (this.opts.maxBudgetUsd !== undefined) {
 72	      const pct = (this.spentUsd / this.opts.maxBudgetUsd) * 100;
 73	      if (pct >= 100) {
 74	        this.exceeded = true;
 75	        signals.push({
 76	          type: "exceeded",
 77	          metric: "cost",
 78	          spent: round2(this.spentUsd),
 79	          cap: this.opts.maxBudgetUsd,
 80	          message: `budget exceeded: $${round2(this.spentUsd).toFixed(2)} spent of $${this.opts.maxBudgetUsd.toFixed(2)} cap`,
 81	        });
 82	        return signals;
 83	      }
 84	      for (const t of this.opts.warnThresholds) {
 85	        if (pct >= t && !this.warned.cost.has(t)) {
 86	          this.warned.cost.add(t);
 87	          signals.push({
 88	            type: "warn",
 89	            metric: "cost",
 90	            thresholdPct: t,
 91	            spent: round2(this.spentUsd),
 92	            cap: this.opts.maxBudgetUsd,
 93	            message: `budget ${t}% — $${round2(this.spentUsd).toFixed(2)} of $${this.opts.maxBudgetUsd.toFixed(2)}`,
 94	          });
 95	        }
 96	      }
 97	    }
 98	
 99	    const tPct = (this.spentTurns / this.opts.maxTurns) * 100;
100	    if (tPct >= 100) {
101	      this.exceeded = true;
102	      signals.push({
103	        type: "exceeded",
104	        metric: "turns",
105	        spent: this.spentTurns,
106	        cap: this.opts.maxTurns,
107	        message: `turn budget exceeded: ${this.spentTurns} turns of ${this.opts.maxTurns}`,
108	      });
109	      return signals;
110	    }
111	    for (const t of this.opts.warnThresholds) {
112	      if (tPct >= t && !this.warned.turns.has(t)) {
113	        this.warned.turns.add(t);
114	        signals.push({
115	          type: "warn",
116	          metric: "turns",
117	          thresholdPct: t,
118	          spent: this.spentTurns,
119	          cap: this.opts.maxTurns,
120	          message: `turns ${t}% — ${this.spentTurns} of ${this.opts.maxTurns}`,
121	        });
122	      }
123	    }
124	
125	    return signals;
126	  }
127	}
128	
129	function round2(n: number): number {
130	  return Math.round(n * 100) / 100;
131	}
