141	    });
142	    session.on("approval", (req: ApprovalRequest) => this.emit("approval", req));
143	    session.on("gateApproval", (g: GateApproval) => this.emit("gateApproval", g));
144	    let result: { verdict: "pass" | "fail" | "halted"; reason?: string };
145	    try { result = await session.run(); } catch (e) { result = { verdict: "halted", reason: String((e as Error).message ?? e) }; }
